class ClassicalGnbEmilCollectorConfigurator:
    def add_emil(self, ne_log_name, ne_log_configuration):
        """
        Add emil collector configuration to the current list of collector configurations
        """

        # check if a collector of same type is already existing
        existing_dcap_collectors = self._collector_configuration_data.find_collectors(
            collector_type='log_collection_classical_gnb_emil')

        if existing_dcap_collectors:
            existing_dcap_collector = existing_dcap_collectors[0]

            # check if the other collector is in same group like the current one
            existing_groups = self._collector_configuration_data.find_parent_groups(
                existing_dcap_collector['name'])
            current_groups = self._collector_configuration_data.find_parent_groups(
                ne_log_name)

            if existing_groups == current_groups and len(existing_groups) == 1:
                # collector is in same group as the existing one - we can merge the two
                self._add_emil_collector_to_existing_collector(existing_dcap_collector)
            else:
                raise AssertionError("Current Configuration not possible!")
        else:
            self._add_emil_collector(ne_log_name, ne_log_configuration)

    def _add_emil_collector_to_existing_collector(self, existing_dcap_collector):
        """
        Add emil to an existing dcap collector. Only the entry for the gnb_custom_profile gets enhanced.

        TODO: The current collector name must be kept in a mapping table, so we are able to detect the
        collector by the collector name later on.
        """
        dcap_collector = self._collector_configuration_data.get_configuration_by_collector_name(
            existing_dcap_collector['collector'])
        if 'cp_5g' not in dcap_collector['trace']['gnb_custom_profile']:
            dcap_collector['trace']['gnb_custom_profile'].append('cp_5g')

    def _add_emil_collector(self, ne_log_name, ne_log_configuration):
        """
        Add a new emil collector configuration to the current list of collector configurations with
        all needed (sub-) collectors.
        """
        oam_http_connection = self.tl_config_information_provider.get_oam_http_connection(self.ne_id)
        backhaul_site_oam_ip = self.tl_config_information_provider.get_backhaul_site_oam_ip(self.ne_id)
        dcap_trace = {
            'bts': {
                'port': '443',
                'host': backhaul_site_oam_ip,
                'username': oam_http_connection.username,
                'password': oam_http_connection.password
            },
            'gnb_custom_profile': ['cp_5g']
        }
        decorated_emil_collector_configuration = {
            'name': f"dcap_{self.ne_type}_{self.ne_id}",
            'type': "dcap",
            'trace': dcap_trace}
        emil_collector_configuration = {
            'name': f"{ne_log_name}",
            'type': "log_collection_classical_gnb_emil",
            'collector': decorated_emil_collector_configuration['name']}
        self._collector_configuration_data.append(decorated_emil_collector_configuration)
        self._collector_configuration_data.append(emil_collector_configuration)

        self._collector_configuration_data.add_mapping_entry(
            log_type='emil',
            network_element=f'{self.ne_type}_{self.ne_id}',
            collector_configuration=emil_collector_configuration)
